//! Against the bundle the firmware embeds (generated by ESP-IDF's
//! gen_crt_bundle.py from firmware/warpaxe/certificates) and the chain
//! api.coingecko.com sends (2026-11-04).

use warpaxe_trust::*;

const BUNDLE: &[u8] = include_bytes!("data/x509_crt_bundle");
/// `GTS Root R4` as api.coingecko.com sends it: cross-signed by
/// `GlobalSign Root CA`, which the bundle no longer has.
const CROSS: &[u8] = include_bytes!("data/gts-r4-cross-signed.der");
/// `GTS Root R4` self-signed, as in the bundle's source.
const SELF: &[u8] = include_bytes!("data/gts-r4-self-signed.der");

/// One DER element at `at`: (tag, content range, end).
fn tlv(d: &[u8], at: usize) -> (u8, core::ops::Range<usize>, usize) {
    let tag = d[at];
    let (len, head) = match d[at + 1] {
        l if l < 0x80 => (usize::from(l), 2),
        l => {
            let n = usize::from(l & 0x7F);
            let len = d[at + 2..at + 2 + n]
                .iter()
                .fold(0, |a, &b| a << 8 | usize::from(b));
            (len, 2 + n)
        }
    };
    (tag, at + head..at + head + len, at + head + len)
}

/// (subject, SubjectPublicKeyInfo) of a certificate, as raw DER, the way
/// mbedTLS hands them over (`subject_raw`, `pk_raw`).
fn subject_and_key(cert: &[u8]) -> (&[u8], &[u8]) {
    let (_, outer, _) = tlv(cert, 0);
    let (_, tbs, _) = tlv(cert, outer.start);
    let mut at = tbs.start;
    let mut fields = Vec::new();
    while at < tbs.end {
        let (tag, _, end) = tlv(cert, at);
        fields.push((tag, at..end));
        at = end;
    }
    // [0] version (explicit, optional), serial, signature, issuer,
    // validity, subject, subjectPublicKeyInfo.
    let skip = usize::from(fields[0].0 == 0xA0);
    let subject = fields[skip + 4].1.clone();
    let spki = fields[skip + 5].1.clone();
    (&cert[subject], &cert[spki])
}

#[test]
fn the_bundle_parses_to_its_118_roots() {
    let b = Bundle::new(BUNDLE).expect("bundle");
    assert_eq!(b.len(), 118);
    assert_eq!(b.entries().count(), 118);
}

#[test]
fn a_cut_bundle_is_refused() {
    assert!(Bundle::new(&BUNDLE[..BUNDLE.len() - 1]).is_none());
    assert!(Bundle::new(&[]).is_none());
}

#[test]
fn the_cross_signed_gts_root_r4_is_the_bundles_root() {
    let b = Bundle::new(BUNDLE).unwrap();
    let (subject, key) = subject_and_key(CROSS);
    assert_eq!(subject_and_key(SELF), (subject, key));
    assert!(b.contains(subject, key));
    assert!(is_sent_root(&b, BADCERT_NOT_TRUSTED, subject, key));
    // An expired cross-signature does not matter for a trust anchor.
    assert!(is_sent_root(
        &b,
        BADCERT_NOT_TRUSTED | BADCERT_EXPIRED,
        subject,
        key
    ));
}

#[test]
fn only_not_trusted_is_ever_overridden() {
    let b = Bundle::new(BUNDLE).unwrap();
    let (subject, key) = subject_and_key(CROSS);
    // Trusted already, or a fault that is not about the anchor.
    assert!(!is_sent_root(&b, 0, subject, key));
    assert!(!is_sent_root(&b, BADCERT_EXPIRED, subject, key));
    // MBEDTLS_X509_BADCERT_REVOKED (0x02), _CN_MISMATCH (0x04).
    assert!(!is_sent_root(&b, BADCERT_NOT_TRUSTED | 0x02, subject, key));
    assert!(!is_sent_root(&b, BADCERT_NOT_TRUSTED | 0x04, subject, key));
}

#[test]
fn the_same_name_with_another_key_is_not_the_root() {
    let b = Bundle::new(BUNDLE).unwrap();
    let (subject, key) = subject_and_key(CROSS);
    let mut other = key.to_vec();
    let last = other.len() - 1;
    other[last] ^= 1;
    assert!(!b.contains(subject, &other));
    assert!(!is_sent_root(&b, BADCERT_NOT_TRUSTED, subject, &other));
    // Nor another name with the root's key.
    let mut name = subject.to_vec();
    let last = name.len() - 1;
    name[last] ^= 1;
    assert!(!is_sent_root(&b, BADCERT_NOT_TRUSTED, &name, key));
    assert!(!is_sent_root(&b, BADCERT_NOT_TRUSTED, &[], &[]));
}

#[test]
fn the_cross_signer_is_not_in_the_bundle() {
    // The issuer of the cross-signed root, GlobalSign Root CA: the reason
    // ESP-IDF's own lookup fails.
    let (_, outer, _) = tlv(CROSS, 0);
    let (_, tbs, _) = tlv(CROSS, outer.start);
    let mut at = tbs.start;
    let mut fields = Vec::new();
    while at < tbs.end {
        let (tag, _, end) = tlv(CROSS, at);
        fields.push((tag, at..end));
        at = end;
    }
    let skip = usize::from(fields[0].0 == 0xA0);
    let issuer = &CROSS[fields[skip + 2].1.clone()];
    let b = Bundle::new(BUNDLE).unwrap();
    assert!(b.entries().all(|(s, _)| s != issuer));
}
